/** How one operation is called. */
export interface OperationRoute {
  /** HTTP method. */
  readonly method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE'
  /** Path, with `{name}` placeholders for its path parameters. */
  readonly path: string
}

